312	  | { readonly kind: "final-route"; readonly tick: number; readonly x: number; readonly y: number; readonly restored: boolean }
313	  | { readonly kind: "final-route-inactive"; readonly tick: number }
314	  /** Minute 20: sectors holding sealed sources and recovery caches. */
315	  | { readonly kind: "sector-reveal"; readonly tick: number; readonly sources: readonly SectorRef[]; readonly caches: readonly SectorRef[] }
316	  /** Minute 28 on: the carriers' sectors and types at the latest snapshot. */
317	  | { readonly kind: "carrier-report"; readonly tick: number; readonly seenTick: number; readonly carriers: readonly (SectorRef & { readonly type: RubbingType })[] };
318	
319	export type IntelMessageKind = IntelMessageBody["kind"];
320	
321	export interface IntelMessage {
322	  readonly to: IntelRecipients;
323	  readonly body: IntelMessageBody;
324	}
325	
326	export interface IntelStepResult {
327	  readonly state: IntelState;
328	  readonly messages: readonly IntelMessage[];
329	  /** One per request, in the order given. */
330	  readonly outcomes: readonly TargetedRumorOutcome[];
331	}
